import json

# Let's search through all JSON files for any 2025 estimate
files = [
    '/app/resources/treasury_bulletin_1994_06.json',
    '/app/resources/treasury_bulletin_1999_06.json', 
    '/app/resources/treasury_bulletin_2004_06.json',
    '/app/resources/treasury_bulletin_2009_06.json',
    '/app/resources/treasury_bulletin_2014_06.json'
]

for f in files:
    try:
        data = json.load(open(f))
        # Search recursively for any number containing 2025
        def search(obj, path=''):
            found = False
            if isinstance(obj, dict):
                for k, v in obj.items():
                    if search(v, f'{path}.{k}'):
                        found = True
            elif isinstance(obj, list):
                for i, v in enumerate(obj):
                    if search(v, f'{path}[{i}]'):
                        found = True
            elif isinstance(obj, (int, float)):
                if obj == 2025 or obj == 2025.0:
                    print(f'Found exact 2025 at {path}: {obj}')
                    return True
                # Check for values that might be 2025 year projections
                if isinstance(obj, (int, float)) and 1000 < obj < 2000000:
                    pass  # This could be a dollar amount
            elif isinstance(obj, str) and '2025' in obj:
                print(f'Found string at {path}: {obj}')
                return True
            return found

        print(f"\n=== Searching {f} ===")
        search(data)
    except Exception as e:
        print(f"Error with {f}: {e}")
