python3 << 'EOF'
# Let me look at ALL content in the 2014 bulletin more comprehensively
# by looking at every element in the JSON

import json

with open('/app/resources/treasury_bulletin_2014_06.json', 'r') as f:
    data = json.load(f)

# Extract all text content from elements
def get_all_text(obj):
    texts = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k == 'content' and isinstance(v, str) and len(v) > 10:
                texts.append(v)
            else:
                texts.extend(get_all_text(v))
    elif isinstance(obj, list):
        for item in obj:
            texts.extend(get_all_text(item))
    return texts

all_texts = get_all_text(data)

# Search for 2025 in context of budget/surplus/deficit
for text in all_texts:
    if '2025' in text:
        if any(w in text.lower() for w in ['deficit', 'surplus', 'receipt', 'outlay', 'budget', 'estimate', 'projection', 'billion']):
            print("Found relevant text:")
            print(text[:500] if len(text) > 500 else text)
            print("-" * 80)
            print()
